from PIL import Image
im = Image.open('radiograph.jpg').convert('L')
regions = {
 'LL_quad': (300, 500, 900, 1050, 2),
 'LR_quad': (1550, 500, 2150, 1050, 2),
}
for name,(x1,y1,x2,y2,f) in regions.items():
    c = im.crop((x1,y1,x2,y2))
    c = c.resize((c.width*f, c.height*f), Image.LANCZOS)
    c.save(f'crop_{name}.png')
    print(name, c.size)
